MAP
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_agua_tratada.log"
    DEBUG 0
    LAYER
        CONNECTIONTYPE POSTGIS
        NAME "SS_MAP_LECT_AGUA_TRATADA"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        INCLUDE 'includes/conexion_gestion_infra.map'
        DATA "gm_predio from ( select gm_predio, no_cuenta, id_predio from op.mv_gm_predio_cuenta_point where cl_tarifa = 'C' ) as pc using unique id_predio using srid=32614" 
        TYPE POINT
        LABELITEM "no_cuenta" 
        LABELCACHE ON
        CLASS
            NAME "Agua Tratada (Pipas)"
            STYLE
                SYMBOL "puntos"
                SIZE 10
                COLOR 0 0 255
                OUTLINECOLOR 0 0 0
            END #STYLE
            LABEL
                TYPE TRUETYPE
                FONT "arial"
                OFFSET 0 12
                SIZE 19
                COLOR 0 0 255
                OUTLINECOLOR 254 254 254
            END #LABEL
        END #CLASS
    END #LAYER
END #MAP
